#!/usr/bin/env node
// scripts/security/tenant-isolation.mjs
//
// Cross-tenant isolation COVERAGE for every public table, plus a generated "guest cannot learn other tenants exist" pgTAP file.
// It builds on scripts/security/rls-audit.mjs (static replay of supabase/migrations) and does not replace it:
//   rls_catalog.test.sql (generated by rls-audit)  -> runtime proof: tenant A vs tenant B for tables the generic probe can seed
//   tenant_isolation_guest.test.sql (generated here) -> runtime proof: guests (anon) read/write nothing of tenant B, A never sees B's profile/team
//   this script                                      -> static coverage report + CI gate: which tables have NO isolation test
//
//   node scripts/security/tenant-isolation.mjs --write              regenerate the report (docs/security/tenant-isolation-coverage.{md,json}) and the guest pgTAP file
//   node scripts/security/tenant-isolation.mjs --update-baseline    create the baseline on first run; afterwards it can only SHRINK (to accept a new gap, edit the JSON by hand in the PR)
//   node scripts/security/tenant-isolation.mjs --check              CI gate
//
// Classification (static, best effort; the pgTAP files are the runtime truth):
//   service-only      RLS on, no policy: clients get nothing (proven by rls_catalog.test.sql check 2)
//   shared-reference  no tenant column and every policy is `true`: shared platform data by design
//   hand-tested       named in a hand-written pgTAP file that impersonates a user (heuristic: the file impersonates a user AND mentions rls/isolation/cross-tenant)
//   generic-probe     has a tenant column and looks seedable with only that column: the generic probe attempts it at runtime
//   gap               none of the above: NO isolation test. Frozen in the baseline; a table that becomes a gap and is not in the baseline FAILS CI.

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { load, splitStatements, stripSql } from "./rls-audit.mjs";
import { posix, readText, sortKeys } from "./lib.mjs";

const HERE = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(HERE, "..", "..");
export const TENANT_COLUMNS = ["user_id", "account_owner_id", "owner_id"];
export const GENERATED_TESTS = new Set(["rls_catalog.test.sql", "tenant_isolation_guest.test.sql"]);
const PATHS = {
  baseline: "docs/security/tenant-isolation-baseline.json",
  md: "docs/security/tenant-isolation-coverage.md",
  json: "docs/security/tenant-isolation-coverage.json",
  guest: "supabase/tests/database/tenant_isolation_guest.test.sql",
};

// ------------------------------------------------------------------ tiny SQL helpers (kept local on purpose)
const IDENT = String.raw`(?:"[^"]+"|[A-Za-z_][\w$]*)`;
const QNAME = String.raw`(?:${IDENT}\.)?${IDENT}`;
const unq = (s) => s.replace(/"/g, "").replace(/^public\./i, "").toLowerCase();
const isPublic = (raw) => !/^"?(?:auth|storage|extensions|cron|net|vault|realtime|graphql\w*|pg_\w+|information_schema|supabase_\w+)"?\./i.test(raw);

function balanced(s, start) {
  let depth = 0;
  for (let i = start; i < s.length; i++) {
    if (s[i] === "'") { i = s.indexOf("'", i + 1); if (i < 0) break; continue; }
    if (s[i] === "(") depth++;
    else if (s[i] === ")" && --depth === 0) return s.slice(start + 1, i);
  }
  return s.slice(start + 1);
}
function topLevelItems(body) {
  const items = []; let depth = 0, cur = "", q = false;
  for (const ch of body) {
    if (ch === "'") q = !q;
    if (!q) { if (ch === "(") depth++; else if (ch === ")") depth--; }
    if (ch === "," && depth === 0 && !q) { items.push(cur.trim()); cur = ""; } else cur += ch;
  }
  if (cur.trim()) items.push(cur.trim());
  return items;
}
const colList = (s) => s.split(",").map((c) => unq(c.trim().split(/\s+/)[0])).filter(Boolean);

// ------------------------------------------------------------------ schema facts: required columns + UNIQUE sets
/** Per table: columns that are NOT NULL (or PK) without a default, and every UNIQUE/PK column set. Best-effort static replay. */
export function parseSchemaFacts(files) {
  const facts = new Map();
  const ensure = (t) => facts.get(t);
  for (const { sql } of files) {
    for (const st of splitStatements(stripSql(sql))) {
      let m;
      if ((m = st.match(new RegExp(`^create\\s+(?:unlogged\\s+)?table\\s+(?:if\\s+not\\s+exists\\s+)?(${QNAME})\\s*\\(`, "i")))) {
        if (!isPublic(m[1])) continue;
        const t = unq(m[1]);
        const f = { required: new Set(), uniques: [] };
        for (const item of topLevelItems(balanced(st, st.indexOf("(", m.index + m[0].length - 1)))) {
          const con = item.match(/^(?:constraint\s+\S+\s+)?(primary\s+key|unique)\s*\(([^)]*)\)/i);
          if (con) { f.uniques.push(colList(con[2])); if (/primary/i.test(con[1])) colList(con[2]).forEach((c) => f.required.add(c)); continue; }
          if (/^(constraint|foreign\s+key|check|exclude|like)\b/i.test(item)) continue;
          const cm = item.match(new RegExp(`^(${IDENT})\\s+\\w+`));
          if (!cm) continue;
          const c = unq(cm[1]);
          const hasDefault = /\bdefault\b|\bgenerated\b/i.test(item);
          if (/\bprimary\s+key\b/i.test(item)) f.uniques.push([c]);
          else if (/\bunique\b/i.test(item)) f.uniques.push([c]);
          if ((/\bnot\s+null\b|\bprimary\s+key\b/i.test(item)) && !hasDefault) f.required.add(c);
        }
        facts.set(t, f);
        continue;
      }
      if ((m = st.match(new RegExp(`^alter\\s+table\\s+(?:if\\s+exists\\s+)?(?:only\\s+)?(${QNAME})\\s+([\\s\\S]*)$`, "i")))) {
        const f = ensure(unq(m[1])); if (!f) continue;
        for (const a of m[2].matchAll(new RegExp(`add\\s+column\\s+(?:if\\s+not\\s+exists\\s+)?(${IDENT})\\s+([^,]*)`, "gi"))) {
          const c = unq(a[1]);
          if (/\bnot\s+null\b/i.test(a[2]) && !/\bdefault\b|\bgenerated\b/i.test(a[2])) f.required.add(c);
          if (/\bunique\b/i.test(a[2])) f.uniques.push([c]);
        }
        for (const a of m[2].matchAll(new RegExp(`alter\\s+column\\s+(${IDENT})\\s+(set\\s+default|drop\\s+not\\s+null)`, "gi"))) f.required.delete(unq(a[1]));
        for (const a of m[2].matchAll(new RegExp(`drop\\s+column\\s+(?:if\\s+exists\\s+)?(${IDENT})`, "gi"))) f.required.delete(unq(a[1]));
        for (const a of m[2].matchAll(/add\s+(?:constraint\s+\S+\s+)?unique\s*\(([^)]*)\)/gi)) f.uniques.push(colList(a[1]));
        continue;
      }
      if ((m = st.match(new RegExp(`^create\\s+unique\\s+index\\s+(?:concurrently\\s+)?(?:if\\s+not\\s+exists\\s+)?${IDENT}?\\s*on\\s+(?:only\\s+)?(${QNAME})\\s*(?:using\\s+\\w+\\s*)?\\(([^)]*)\\)`, "i")))) {
        const f = ensure(unq(m[1])); if (!f) continue;
        if (!/\bwhere\b/i.test(st)) f.uniques.push(colList(m[2])); // partial unique indexes are not a global oracle
      }
    }
  }
  return facts;
}

// ------------------------------------------------------------------ hand-written coverage
const IMPERSONATION = /request\.jwt\.claim|set_config\(\s*'role'|set\s+local\s+role|set\s+role\s+(?:authenticated|anon)|act_as\s*\(|auth\.uid/i;
// The file must also SAY it is about isolation (comments count); a fixture that merely inserts into a table is not a test of it.
const ISOLATION_MARKER = /\b(?:rls|tenant[\s_-]*isolation|cross[\s_-]*tenant|other[\s_-]*tenant|another[\s_-]*tenant|isolation)\b/i;

/** Tables named in hand-written pgTAP files that impersonate users. Heuristic: it proves a test EXISTS near the table, not that it is correct. */
export function detectHandTested(testDir, names) {
  const known = new Set(names);
  const out = new Map();
  if (!fs.existsSync(testDir)) return out;
  for (const f of fs.readdirSync(testDir).filter((x) => x.endsWith(".test.sql") && !GENERATED_TESTS.has(x)).sort()) {
    const raw = readText(path.join(testDir, f));
    const text = stripSql(raw);
    if (!IMPERSONATION.test(text) || !(ISOLATION_MARKER.test(raw) || ISOLATION_MARKER.test(f))) continue;
    for (const id of new Set(text.toLowerCase().match(/[a-z_][a-z0-9_]*/g) ?? [])) if (known.has(id) && !out.has(id)) out.set(id, f);
  }
  return out;
}

// ------------------------------------------------------------------ classification
const isTrue = (e) => e !== null && /^\s*true\s*$/i.test(e);

export function classify(tables, facts, handTested) {
  const rows = [];
  for (const t of [...tables.values()].sort((a, b) => a.name.localeCompare(b.name))) {
    if (!t.rls) continue; // "no RLS" is rls-audit's finding, not an isolation-coverage question
    const tenantCol = TENANT_COLUMNS.find((c) => t.cols.has(c)) ?? null;
    const row = { table: t.name, tenantColumn: tenantCol, status: "gap", reason: "", evidence: "" };
    const f = facts.get(t.name);
    if (t.policies.size === 0) { row.status = "service-only"; row.reason = "RLS on, no policy"; }
    else if (handTested.has(t.name)) { row.status = "hand-tested"; row.evidence = handTested.get(t.name); }
    else if (!tenantCol) {
      const open = [...t.policies.values()].every((p) => (p.cmd === "select" || p.cmd === "all") ? isTrue(p.using) || isTrue(p.check) : true);
      if (open) { row.status = "shared-reference"; row.reason = "no tenant column; policies are `true`"; }
      else row.reason = "no tenant column: isolation depends on a join/membership/token predicate nobody tests";
    } else {
      const extra = f ? [...f.required].filter((c) => c !== tenantCol) : [];
      if (extra.length === 0) { row.status = "generic-probe"; row.evidence = "rls_catalog.test.sql"; }
      else row.reason = `generic probe cannot seed it (also requires: ${extra.slice(0, 4).join(", ")}${extra.length > 4 ? ", …" : ""})`;
    }
    rows.push(row);
  }
  return rows;
}

/** Global UNIQUE columns on tenant tables: INSERT/UPSERT conflict errors can reveal that another tenant owns the value (T6 oracle candidates). Report only. */
export function enumerationOracles(tables, facts) {
  const out = [];
  for (const t of tables.values()) {
    const tenantCol = TENANT_COLUMNS.find((c) => t.cols.has(c));
    const f = facts.get(t.name);
    if (!tenantCol || !f || !t.rls || t.policies.size === 0) continue;
    for (const u of f.uniques) {
      if (u.includes(tenantCol) || (u.length === 1 && u[0] === "id")) continue;
      out.push({ table: t.name, columns: u.join(", ") });
    }
  }
  const seen = new Set();
  return out.filter((o) => { const k = `${o.table}|${o.columns}`; if (seen.has(k)) return false; seen.add(k); return true; }).sort((a, b) => (a.table + a.columns).localeCompare(b.table + b.columns));
}

/** Tables that are readable by guests ON PURPOSE: a policy for anon/public whose predicate is `true`. Excluded from the "guest reads nothing" check. */
export function anonByDesign(tables) {
  const names = [];
  for (const t of tables.values()) {
    if (!t.rls) continue;
    const open = [...t.policies.values()].some((p) => (p.cmd === "select" || p.cmd === "all") && p.roles.some((r) => r === "anon" || r === "public") && isTrue(p.using));
    if (open) names.push(t.name);
  }
  return names.sort();
}

// ------------------------------------------------------------------ gate
export function gate(rows, baseline) {
  const errors = [];
  const gaps = new Set(rows.filter((r) => r.status === "gap").map((r) => r.table));
  const frozen = new Set(baseline.gaps ?? []);
  for (const r of rows) {
    if (r.status === "gap" && !frozen.has(r.table)) {
      errors.push(`${r.table}: NEW tenant table without an isolation test (${r.reason}). Add a hand-written pgTAP test that impersonates two tenants (see docs/security/tenant-isolation-coverage.md), or make it seedable by the generic probe.`);
    }
  }
  for (const t of frozen) if (!gaps.has(t)) errors.push(`baseline gap "${t}" is closed or gone — run: node scripts/security/tenant-isolation.mjs --update-baseline`);
  return errors;
}

// ------------------------------------------------------------------ rendering
const ORDER = ["gap", "hand-tested", "generic-probe", "shared-reference", "service-only"];

export function summarize(rows) {
  const s = Object.fromEntries(ORDER.map((k) => [k, 0]));
  for (const r of rows) s[r.status]++;
  return { tables: rows.length, ...s };
}

export function renderMd(rows, oracles, anonList, baseline) {
  const s = summarize(rows);
  const L = [
    "# Tenant isolation coverage",
    "",
    "> Generated by `node scripts/security/tenant-isolation.mjs --write` from a static replay of `supabase/migrations`. Statuses are a best-effort static prediction; the runtime proof is `supabase/tests/database/rls_catalog.test.sql` (tenant A vs B) and `supabase/tests/database/tenant_isolation_guest.test.sql` (guests).",
    "",
    "## Summary",
    "",
    "| Status | Tables | Meaning |",
    "|---|---:|---|",
    `| gap | ${s.gap} | No isolation test. Frozen in \`tenant-isolation-baseline.json\`; new ones fail CI |`,
    `| hand-tested | ${s["hand-tested"]} | Named in a hand-written pgTAP file that impersonates a user (heuristic) |`,
    `| generic-probe | ${s["generic-probe"]} | Has a tenant column and looks seedable; probed by \`rls_catalog.test.sql\` at runtime |`,
    `| shared-reference | ${s["shared-reference"]} | No tenant column, \`true\` policies: shared platform data by design |`,
    `| service-only | ${s["service-only"]} | RLS on, no policy: clients get nothing |`,
    `| **Total (RLS tables)** | ${s.tables} | |`,
    "",
    `Baseline gaps: ${(baseline.gaps ?? []).length}. Guests may read ${anonList.length} table(s) by design (excluded from the guest check).`,
    "",
    "## How to close a gap",
    "",
    "1. Copy the pattern from `supabase/tests/database/commercial_approval_to_cash.test.sql` (two tenants, `act_as`, assert A cannot select/update/delete/insert B's row).",
    "2. Run `node scripts/security/tenant-isolation.mjs --update-baseline`; the table leaves the baseline and the baseline shrinks.",
    "",
    `## Untested tables — gaps (${s.gap})`,
    "",
    "| Table | Tenant column | Why it is a gap |",
    "|---|---|---|",
    ...rows.filter((r) => r.status === "gap").map((r) => `| \`${r.table}\` | ${r.tenantColumn ? `\`${r.tenantColumn}\`` : "—"} | ${r.reason} |`),
    "",
    `## Guests can read by design (${anonList.length})`,
    "",
    anonList.length ? anonList.map((t) => `\`${t}\``).join(", ") : "_None._",
    "",
    `## Enumeration-oracle candidates (${oracles.length}) — report only`,
    "",
    "Tenant tables with a UNIQUE key that does not include the tenant column. A conflict error on insert/upsert can tell a user that ANOTHER tenant already holds a value (T6). Review each: scope the key by tenant, or return a uniform error.",
    "",
    oracles.length ? ["| Table | Unique on |", "|---|---|", ...oracles.map((o) => `| \`${o.table}\` | ${o.columns} |`)].join("\n") : "_None._",
    "",
  ];
  return L.join("\n");
}

const sqlArr = (xs) => (xs.length ? `array[${xs.map((x) => `'${x.replace(/'/g, "''")}'`).join(", ")}]::text[]` : "array[]::text[]");

export function renderGuestPgtap(anonList) {
  return `-- GENERATED by scripts/security/tenant-isolation.mjs --write. Do not edit by hand.
-- T6 (identity-authz-audit): a guest must not be able to learn that other tenants, or their data, exist.
--   1. for every tenant-column table with a policy: a seeded tenant-B row is invisible to anon (count 0 or permission denied),
--      and anon cannot INSERT / UPDATE / DELETE it. Tables guests may read on purpose are listed below and skipped.
--   2. tenant A never sees tenant B's profile or team, and cannot read auth.users.
--   3. report-only: SECURITY DEFINER functions executable by anon (review each: a guest-callable function is the usual enumeration channel).
-- Tables the generic seeding cannot insert into (only the tenant column is supplied) are reported with skip() — NOT proven here.
begin;
create extension if not exists pgtap with schema extensions;
select * from no_plan();

create temp table _guest_by_design as select unnest(${sqlArr(anonList)}) as t;
create temp table _guest_probe(tbl text, col text, seeded boolean, read_ok boolean, insert_ok boolean, update_ok boolean, delete_ok boolean);

create or replace function pg_temp._guest_run() returns void language plpgsql as $f$
declare
  r record; n bigint; seeded boolean; rd boolean; ins boolean; up boolean; de boolean;
  b uuid := '00000000-0000-0000-0000-00000000b0b1';
begin
  insert into auth.users (id, email) values (b, 'tenant-b@guest-probe.test') on conflict do nothing;
  for r in
    select c.oid, c.relname,
           (select a2.attname from pg_attribute a2 where a2.attrelid = c.oid and not a2.attisdropped and a2.atttypid = 'uuid'::regtype
              and a2.attname in ('user_id','account_owner_id','owner_id') order by array_position(array['user_id','account_owner_id','owner_id'], a2.attname::text) limit 1) as tcol
    from pg_class c join pg_namespace ns on ns.oid = c.relnamespace
    where ns.nspname = 'public' and c.relkind = 'r' and c.relrowsecurity
      and exists (select 1 from pg_policy p where p.polrelid = c.oid)
      and c.relname not in (select t from _guest_by_design)
    order by c.relname
  loop
    continue when r.tcol is null;
    seeded := false; rd := null; ins := null; up := null; de := null;
    begin
      execute 'reset role';
      execute format('insert into public.%I (%I) values ($1)', r.relname, r.tcol) using b;
      execute format('select count(*) from public.%I where %I = $1', r.relname, r.tcol) into n using b;
      seeded := n > 0;
    exception when others then seeded := false;
    end;
    if seeded then
      perform set_config('request.jwt.claim.sub', '', true);
      perform set_config('request.jwt.claims', json_build_object('role', 'anon')::text, true);
      begin execute 'set local role anon'; execute format('select count(*) from public.%I where %I = $1', r.relname, r.tcol) into n using b; rd := (n = 0);
      exception when insufficient_privilege then rd := true; when others then rd := false; end;
      begin execute 'set local role anon'; execute format('insert into public.%I (%I) values ($1)', r.relname, r.tcol) using b; ins := false;
      exception when insufficient_privilege then ins := true; when others then ins := true; end;   -- any failure (RLS, NOT NULL, ...) means no row was written
      begin execute 'set local role anon'; execute format('update public.%I set %I = %I where %I = $1', r.relname, r.tcol, r.tcol, r.tcol) using b; get diagnostics n = row_count; up := (n = 0);
      exception when insufficient_privilege then up := true; when others then up := false; end;
      begin execute 'set local role anon'; execute format('delete from public.%I where %I = $1', r.relname, r.tcol) using b; get diagnostics n = row_count; de := (n = 0);
      exception when insufficient_privilege then de := true; when others then de := false; end;
      execute 'reset role';
    end if;
    insert into _guest_probe values (r.relname, r.tcol, seeded, rd, ins, up, de);
  end loop;
  execute 'reset role';
end $f$;
select pg_temp._guest_run();

select ok(read_ok,   tbl || ': guest cannot read tenant rows (' || col || ')') from _guest_probe where seeded order by tbl;
select ok(insert_ok, tbl || ': guest cannot insert a tenant row') from _guest_probe where seeded order by tbl;
select ok(update_ok, tbl || ': guest cannot update tenant rows') from _guest_probe where seeded order by tbl;
select ok(delete_ok, tbl || ': guest cannot delete tenant rows') from _guest_probe where seeded order by tbl;
select skip(1, tbl || ': not seedable with only ' || col || ' — NOT proven for guests; needs a hand-written test') from _guest_probe where not seeded order by tbl;
select diag('guest probe coverage: ' || count(*) filter (where seeded) || ' tables proven, ' || count(*) filter (where not seeded) || ' not seedable (skipped)') from _guest_probe;

-- 2. one tenant never sees another tenant's profile / team
insert into auth.users (id, email) values
  ('00000000-0000-0000-0000-00000000a0a1', 'tenant-a@guest-probe.test'),
  ('00000000-0000-0000-0000-00000000b0b1', 'tenant-b@guest-probe.test')
on conflict do nothing;
insert into public.profiles (id, role) values
  ('00000000-0000-0000-0000-00000000a0a1', 'owner'),
  ('00000000-0000-0000-0000-00000000b0b1', 'owner')
on conflict (id) do nothing;

select set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-00000000a0a1', true);
select set_config('request.jwt.claims', '{"sub":"00000000-0000-0000-0000-00000000a0a1","role":"authenticated"}', true);
set local role authenticated;
select is((select count(*)::int from public.profiles where id = '00000000-0000-0000-0000-00000000b0b1'), 0, 'tenant A cannot see tenant B''s profile');
select is((select count(*)::int from public.team_members where account_owner_id = '00000000-0000-0000-0000-00000000b0b1'), 0, 'tenant A cannot see tenant B''s team');
select throws_ok($$ select count(*) from auth.users $$, '42501', null, 'authenticated clients cannot read auth.users');
reset role;

-- 3. report-only: anon-executable SECURITY DEFINER functions (guest-callable code paths)
select diag('anon-executable SECURITY DEFINER functions (review): ' || coalesce(string_agg(p.proname, ', ' order by p.proname), 'none'))
from pg_proc p join pg_namespace n on n.oid = p.pronamespace
where n.nspname = 'public' and p.prosecdef and has_function_privilege('anon', p.oid, 'execute');

select * from finish();
rollback;
`;
}

// ------------------------------------------------------------------ CLI
export function readMigrations(root = ROOT) {
  const dir = path.join(root, "supabase", "migrations");
  return fs.readdirSync(dir).filter((f) => f.endsWith(".sql")).sort().map((f) => ({ name: f, sql: readText(path.join(dir, f)) }));
}

export function analyze(root = ROOT) {
  const { tables } = load(root);
  const facts = parseSchemaFacts(readMigrations(root));
  const handTested = detectHandTested(path.join(root, "supabase", "tests", "database"), [...tables.keys()]);
  return { tables, rows: classify(tables, facts, handTested), oracles: enumerationOracles(tables, facts), anonList: anonByDesign(tables) };
}

function main() {
  const args = new Set(process.argv.slice(2));
  const out = (p) => path.join(ROOT, p);
  const { rows, oracles, anonList } = analyze();
  const gapsNow = rows.filter((r) => r.status === "gap").map((r) => r.table);
  const basePath = out(PATHS.baseline);
  const baseExists = fs.existsSync(basePath);
  let baseline = baseExists ? JSON.parse(readText(basePath)) : { version: 1, gaps: [] };

  if (args.has("--update-baseline")) {
    // First run: freeze today's gaps. Afterwards: only shrink. Accepting a NEW gap must be a visible, hand-made edit of the JSON.
    const next = baseExists ? baseline.gaps.filter((t) => gapsNow.includes(t)) : gapsNow;
    baseline = { version: 1, note: "Tenant tables with no isolation test. Only ever shrink. Generated by scripts/security/tenant-isolation.mjs --update-baseline.", gaps: [...next].sort() };
    fs.writeFileSync(basePath, `${JSON.stringify(sortKeys(baseline), null, 2)}\n`);
    console.log(`tenant-isolation baseline: ${baseline.gaps.length} gaps${baseExists ? " (shrink only)" : " (created)"}`);
  }

  const artifacts = {
    [PATHS.md]: renderMd(rows, oracles, anonList, baseline),
    [PATHS.json]: `${JSON.stringify(sortKeys({ version: 1, summary: summarize(rows), gaps: gapsNow, oracles, anonByDesign: anonList }), null, 2)}\n`,
    [PATHS.guest]: renderGuestPgtap(anonList),
  };

  if (args.has("--write") || args.has("--update-baseline")) {
    for (const [p, text] of Object.entries(artifacts)) fs.writeFileSync(out(p), text);
    console.log(`wrote ${Object.keys(artifacts).map(posix).join(", ")}`);
    return;
  }
  if (args.has("--check")) {
    const errors = [];
    if (!baseExists) errors.push(`${PATHS.baseline} is missing — run once and commit: node scripts/security/tenant-isolation.mjs --update-baseline`);
    else errors.push(...gate(rows, baseline));
    for (const [p, text] of Object.entries(artifacts)) if (!fs.existsSync(out(p)) || readText(out(p)) !== text) errors.push(`${p} is stale — run: node scripts/security/tenant-isolation.mjs --write`);
    if (errors.length) { console.error(`Tenant isolation gate FAILED (${errors.length}):`); for (const e of errors) console.error(`  - ${e}`); process.exit(1); }
    console.log(`Tenant isolation gate passed (${rows.length} RLS tables, ${gapsNow.length} frozen gaps).`);
    return;
  }
  console.log(JSON.stringify({ summary: summarize(rows), gaps: gapsNow.length, oracles: oracles.length, anonByDesign: anonList.length }, null, 2));
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) main();
